/* ---------------------------------------------------------------------------
   The monastic cowl.

   Every head above is bare — tonsured, plain-haired or wearing 1920s hats — so
   a Cultist only ever read as a monk when the cult-regalia layer happened to
   roll a hood, which is the demo crowd only: the player, other players and the
   Abbot are all drawn straight from the sprite sheet with no regalia, so they
   walked the abbey bare-headed.

   Rather than hand-author another 96 rows of art data, the cowl is DERIVED from
   the 'bald' head: widen the silhouette by two cells so the cloth sits over the
   skull rather than painted on it, then convert every skin/hair cell outside a
   face window into hood cloth (H/h/2, which take the habit's own wool ramp, so
   the hood always matches the robe). Eyes and mouth (E/W/M) are never touched.
   Shading follows the same upper-left key light as the rest of the abbey: lit
   rim on the left, base across the crown, shadow down the right, and a dark
   inner lip where the cloth turns into the opening.                          */
function cowlFrom(rows, dir) {
  const WID = rows[0].length;
  // no face window on the back of the head — the hood closes over it
  // Side view: the face sits left of centre (eyes around x5-12), so the window
  // is tighter and pushed forward — a cowl in profile has to come down over the
  // brow and cheek, otherwise the hood reads as a scarf sitting behind the head.
  const face = dir === 'up' ? null
    : dir === 'side' ? { cx: 6.6, cy: 17.4, rx: 6.6, ry: 6.8 }
      : { cx: 17.5, cy: 17.5, rx: 9.6, ry: 7.8 };
  const inFace = (x, y) => !!face
    && ((x - face.cx) ** 2) / (face.rx ** 2) + ((y - face.cy) ** 2) / (face.ry ** 2) <= 1;

  return rows.map((row, y) => {
    const cells = [...row];
    // 1. drape: widen the head's span so the cowl reads as cloth over the skull
    if (y <= 26) {
      const first = cells.findIndex((c) => c !== '.');
      if (first >= 0) {
        const last = WID - 1 - [...cells].reverse().findIndex((c) => c !== '.');
        const grow = y <= 23 ? 2 : 1;
        for (let d = 1; d <= grow; d++) {
          // In profile the face is at the LOW-x end, so draping that side puts
          // cloth across the front of the face — a hood worn over the nose.
          // The cowl only grows backward and over the crown when side-on; the
          // front-facing views still drape both cheeks, which is correct there.
          if (first - d >= 0 && dir !== 'side') cells[first - d] = 'H';
          if (last + d < WID) cells[last + d] = 'H';
        }
      }
    }
    // 2. cloth: everything outside the face window that isn't an eye or mouth
    const span0 = cells.findIndex((c) => c !== '.');
    const span1 = WID - 1 - [...cells].reverse().findIndex((c) => c !== '.');
    for (let x = 0; x < WID; x++) {
      const c = cells[x];
      if (c === '.' || c === 'E' || c === 'W' || c === 'M') continue;
      if (!'Ss12HhKk'.includes(c)) continue;
      if (inFace(x, y)) continue;
      const nearOpening = face
        && ((x - face.cx) ** 2) / ((face.rx + 1.7) ** 2)
          + ((y - face.cy) ** 2) / ((face.ry + 1.5) ** 2) <= 1;
      if (nearOpening) { cells[x] = 'h'; continue; }        // dark inner lip
      const mid = (span0 + span1) / 2;
      if (x <= span0 + 1 && y <= 24) cells[x] = '2';        // lit upper-left rim
      else if (x >= span1 - 1 || y >= 25) cells[x] = 'h';   // turning shadow
      else if (!face && y <= 5) cells[x] = '2';             // lit crown, back view
      else if (!face && Math.abs(x - mid) < 1 && y >= 6) cells[x] = 'h'; // centre seam
      else if (!face && x < mid - 1 && y <= 18) cells[x] = '2'; // key-lit left half
      else cells[x] = 'H';
    }
    return cells.join('');
  });
}
/* ---------------------------------------------------------------------------
   LttP faces.

   The ported generator draws a 1920s-cartoon face: each eye is an 8x9 cell
   cluster (4 x 4.5 logical px) built from a white sclera with an iris ring
   around it, plus a mouth. Two of those fill most of the head, which is what
   makes these read as mascots rather than as SNES overworld sprites.

   A Link to the Past draws an overworld face with almost nothing: no sclera, no
   mouth, no brow. An eye is a small dark mark, and the character is carried by
   silhouette and shading instead. This collapses each cluster down to that —
   clear the sclera/iris/mouth back to skin, then stamp one 3x4 cell mark per
   eye (roughly 1.5 x 2 logical px), nudged inward because the cartoon eyes sat
   far wider apart than LttP ever places them.

   Only skin cells are ever stamped on, so a cowl's cloth is never punched
   through, and heads with no face at all (the back of the head) are untouched. */
const FACE_CACHE = new Map();
function lttpFace(rows, dir, key) {
  const ck = `${key}|${dir}`;
  const hit = FACE_CACHE.get(ck);
  if (hit) return hit;

  const WID = rows[0].length;
  const cells = rows.map((r) => [...r]);
  const eye = [];
  for (let y = 0; y < cells.length; y++) {
    for (let x = 0; x < WID; x++) {
      const c = cells[y][x];
      if (c === 'E' || c === 'W') eye.push([x, y]);
      if (c === 'E' || c === 'W' || c === 'M') cells[y][x] = 'S';   // back to skin
    }
  }
  if (eye.length) {
    const xs = eye.map((p) => p[0]);
    const mid = (Math.min(...xs) + Math.max(...xs)) / 2;
    const groups = dir === 'side'
      ? [eye]
      : [eye.filter((p) => p[0] < mid), eye.filter((p) => p[0] >= mid)];
    for (const g of groups) {
      if (!g.length) continue;
      const gx = g.map((p) => p[0]), gy = g.map((p) => p[1]);
      let cx = Math.round((Math.min(...gx) + Math.max(...gx)) / 2);
      const cy = Math.round((Math.min(...gy) + Math.max(...gy)) / 2);
      if (dir !== 'side') cx += cx < mid ? 2 : -2;   // draw the eyes closer in
      for (let dy = -1; dy <= 2; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          const x = cx + dx, y = cy + dy;
          if (!cells[y] || !cells[y][x]) continue;
          if (!'Ss1'.includes(cells[y][x])) continue;  // never punch through cloth
          cells[y][x] = 'E';
        }
      }
    }
  }
  const out = cells.map((c) => c.join(''));
  FACE_CACHE.set(ck, out);
  return out;
}
/* The ported row data disagrees with itself about who has hair.

   Counting hair cells (K/k) in the head rows of each style, front against
   profile: bald is 28 / 97, and every hat — fez, topper, bowler, fedora,
   boater, newsboy, cloche, turban — is 0 / 170ish. So a shaven cultist and
   every hatted one grow a full mass of hair the instant they turn sideways,
   and lose it again when they turn back. That is the "hair showing weird from
   the sides": it is not a shading problem, the hair is simply not supposed to
   be there.

   Rather than hand-edit twenty-two blocks of row data, the profile is made to
   agree with the front. If a style shows little or no hair head-on, its
   profile hair is repainted as skin — K to S, k to s, keeping the light and
   shadow steps so the skull still reads as rounded. Styles that genuinely have
   hair (wavy 272/320, curly 410/460, slick 158/189…) are far above the
   threshold and are left exactly as drawn. */
const HEAD_ROWS = 22;                 // rows of the 32 that are head, not neck
const HAIR_MATCH = 0.45;              // profile hair is a lie below this ratio

function hairCells(rows) {
  let n = 0;
  for (let y = 0; y < Math.min(HEAD_ROWS, rows.length); y++) {
    for (const c of rows[y]) if (c === 'K' || c === 'k') n++;
  }
  return n;
}

const HAIR_FIX = new Map();
function matchHairToFront(h, name, view) {
  const key = `${name}|${view}`;
  if (HAIR_FIX.has(key)) return HAIR_FIX.get(key);
  const front = hairCells(h.down);
  const rows = h[view];
  const here = hairCells(rows);
  let out = rows;
  if (here > 0 && front / here < HAIR_MATCH) {
    out = rows.map((row, y) => (y >= HEAD_ROWS ? row
      : [...row].map((c) => (c === 'K' ? 'S' : c === 'k' ? 's' : c)).join('')));
  }
  HAIR_FIX.set(key, out);
  return out;
}

function lttpHead(name) {
  const h = HD_HEADS[name] || HD_HEADS.cowl;
  // A bird carries its own face, so both of the passes below have to be skipped
  // for it. They exist to make HUMAN heads agree with one another across views:
  //   - lttpFace() resets every E/W/M cell to skin and re-stamps an LttP face at
  //     human coordinates — two eyes where a bird has one, and nothing at all
  //     where the beak is. It was deleting the bird's face and painting a
  //     person's over it.
  //   - matchHairToFront() swaps a view whose hair-cell ratio falls under
  //     HAIR_MATCH, on the theory that a profile with too little hair is a lie.
  //     A bird has NO hair cells, so it tripped on every view and every frame
  //     came back facing front.
  // A generated bird head already agrees with itself in all three views.
  if (name === 'bird' || name === 'birdcowl') return { down: h.down, up: h.up, side: h.side };
  return {
    down: lttpFace(h.down, 'down', name),
    // The BACK view has the same disagreement as the profile — bald is 28 hair
    // cells from the front and 96 from behind — and it is the view the shrine
    // rite spends most of its time in, with the worshipper turned away.
    up: lttpFace(matchHairToFront(h, name, 'up'), 'up', name),
    side: lttpFace(matchHairToFront(h, name, 'side'), 'side', name),
  };
}

HD_HEADS.cowl = {
  down: cowlFrom(HD_HEADS.bald.down, 'down'),
  up: cowlFrom(HD_HEADS.bald.up, 'up'),
  side: cowlFrom(HD_HEADS.bald.side, 'side'),
};

/* ===== THE BIRD ABBEY =====================================================
   Every head above is hand-authored as 32 rows of 36 characters. A bird only
   varies in three things — skull, beak and the socket over the eye — so it is
   GENERATED rather than typed out three times. The output is the same rows of
   the same letters the hand-authored heads use, so everything downstream
   (cowlFrom, lttpFace, the outline pass, the regalia in cultLook) treats it as
   just another head and needs no special case.

   New letters: P and p, beak and talon keratin. It is neither plumage nor
   cloth — it takes a harder, yellower ramp than either — so reusing S or Y
   would have shaded it wrong. */
const BW = 36, BH = 32;
function bBlank() { return Array.from({ length: BH }, () => Array(BW).fill('.')); }
function bPut(g, x, y, c) { if (y >= 0 && y < BH && x >= 0 && x < BW) g[y][x] = c; }
function bEllipse(g, cx, cy, rx, ry, c) {
  for (let y = 0; y < BH; y++) for (let x = 0; x < BW; x++) {
    const dx = (x - cx) / rx, dy = (y - cy) / ry;
    if (dx * dx + dy * dy <= 1) bPut(g, x, y, c);
  }
}
// Shade the lower-right, light the upper-left: the same key light every other
// material in the abbey obeys.
function bShade(g) {
  const snap = g.map((r) => r.slice());
  for (let y = 0; y < BH; y++) for (let x = 0; x < BW; x++) {
    if (snap[y][x] !== 'S') continue;
    // Shade the lower-right edge only. Lighting the upper-left edge as well
    // left a nine-pixel skull with almost no base colour in it at all — every
    // cell touches an edge at that radius — and the plumage washed out to its
    // own highlight.
    if ((x + 1 < BW && snap[y][x + 1] === '.') || (y + 1 < BH && snap[y + 1][x] === '.')) bPut(g, x, y, 's');
  }
}
function bEye(g, ex, ey, r) {
  bEllipse(g, ex, ey, r + 0.8, r + 0.8, 'W');
  bEllipse(g, ex, ey, r, r, 'E');
  bPut(g, ex - 1, ey - 1, 'W');            // one catchlight pixel, not a ring
}

function birdHeadRows(dir) {
  const g = bBlank();
  const cx = 18, cy = 16, rx = 9, ry = 8.5;
  bEllipse(g, cx, cy, rx, ry, 'S');
  bEllipse(g, cx - 1, cy + 2, rx - 1, ry - 2, 'S');   // jowl
  bEllipse(g, cx - 3, cy + 4, rx - 4, ry - 4, 'S');   // nape, following the curve

  if (dir === 'side') {
    // The bird's own view: beak in profile, one eye. This is the reference
    // pose and the one the player sees most, walking left and right.
    for (let x = cx - 2; x <= cx + 6; x++) bPut(g, x, cy - 5, 's');   // brow shelf
    const bx = cx + 7, by = cy + 1;
    for (let i = 0; i < 9; i++) {
      const t = i < 3 ? 2 : (i < 6 ? 1 : 0);
      for (let j = -t; j <= t; j++) bPut(g, bx + i, by + j + (i > 5 ? 1 : 0), 'P');
    }
    for (let i = 2; i < 8; i++) bPut(g, bx + i, by + 1, 'p');          // the gape, one line
    bShade(g);
    bEye(g, cx + 4, cy - 2, 1.8);
  } else if (dir === 'down') {
    // Facing the player. The first attempt put two eyes close together with a
    // small wedge under them, which is a HUMAN face — eyes to the front, nose
    // between and below. A bird's eyes sit on the SIDES of its skull and the
    // beak starts up between them and runs down past the jaw, so the beak is
    // the largest thing on the face rather than an afterthought beneath it.
    for (let x = cx - 7; x <= cx + 7; x++) bPut(g, x, cy - 5, 's');   // brow shelf
    bShade(g);
    // Beak first, eyes after, so nothing overdraws an eye.
    for (let i = 0; i < 10; i++) {
      const t = Math.max(0, 3 - Math.floor(i / 2.4));
      for (let j = -t; j <= t; j++) bPut(g, cx + j, cy - 2 + i, 'P');
    }
    for (let j = -3; j <= 3; j++) bPut(g, cx + j, cy - 1, 'p');       // the gape, across
    // Out at the temples, where a bird's actually are.
    bEye(g, cx - 6, cy - 2, 1.8);
    bEye(g, cx + 6, cy - 2, 1.8);
  } else {
    // Turned away: no beak, no eyes. Just the back of the skull and the nape —
    // which is most of what the shrine rite looks at.
    bShade(g);
  }
  return g.map((r) => r.join(''));
}

HD_HEADS.bird = { down: birdHeadRows('down'), up: birdHeadRows('up'), side: birdHeadRows('side') };
// Hooded, for everyone who wears the habit's cowl. The derivation is the same
// one the human cowl uses, so the beak emerges from under the hood exactly the
// way a human face did.
HD_HEADS.birdcowl = {
  down: cowlFrom(HD_HEADS.bird.down, 'down'),
  up: cowlFrom(HD_HEADS.bird.up, 'up'),
  side: cowlFrom(HD_HEADS.bird.side, 'side'),
};

