/* Paints a block of rows at an arbitrary cell size, horizontally centred in the
   sprite's 18-logical-px content box, with its top edge at yTop. The cell size
   is a parameter (it used to be hardcoded at 0.5 for every part) so the head
   and the body can be drawn at different scales — see PROPORTIONS below. */
function paintRowsHD(g, rows, pal, yTop, cell) {
  const x0 = (18 - rows[0].length * cell) / 2;
  for (let y = 0; y < rows.length; y++) {
    const r = rows[y];
    for (let x = 0; x < r.length; x++) {
      const ch = r[x];
      if (ch === '.' || !pal[ch]) continue;
      g.fillStyle = pal[ch];
      g.fillRect(x0 + x * cell, yTop + y * cell, cell, cell);
    }
  }
}

/* PROPORTIONS.

   The ported generator draws every part at the same 0.5 cell size, which puts
   the head at 16 of the figure's 26 logical px — 61%, or about 1.6 heads tall.
   That is a mascot build. A Link to the Past draws its overworld cast at
   roughly 2 to 2.5 heads: Link is 24px with a ~10px head, about 42%.

   Shrinking the head cell and growing the body/leg cell moves us most of the
   way there without touching a single row of art data. Feet stay pinned at
   y=26 so the sprite keeps its existing ground line and nothing else in the
   scene has to move. */
// Tuned by eye against the reference build. The row data has a 32-row head but
// only 20 rows of body+legs, so matching LttP's head fraction exactly would
// need shoulders far wider than the head; 0.42/0.55 lands the head near half
// the figure with shoulders about a sixth wider, which reads as a robed adult
// rather than either a mascot or a pinhead on a slab.
const HEAD_CELL = 0.42;   // 32 rows -> 13.4 logical px tall, 15.1 wide
const BODY_CELL = 0.55;   // 12 rows -> 6.6 body, 8 rows -> 4.4 legs, 17.6 wide
const FEET_Y = 26;
const HEAD_H = 32 * HEAD_CELL, BODY_H = 12 * BODY_CELL, LEGS_H = 8 * BODY_CELL;
const HEAD_Y = FEET_Y - (HEAD_H + BODY_H + LEGS_H);
const BODY_Y = HEAD_Y + HEAD_H;
const LEGS_Y = BODY_Y + BODY_H;
/* Outline + interior edge-lighting pass. Two of the world's rules land here:
   a coloured outline in each material's own hue, and a consistent upper-left
   key light expressed as a lit inner edge / cool turning shadow. */
function outlineHD(c) {
  const w = c.width, h = c.height;
  const g = c.getContext('2d');
  const src = g.getImageData(0, 0, w, h);
  const out = g.createImageData(w, h);
  const A = (x, y) => (x < 0 || y < 0 || x >= w || y >= h) ? 0 : src.data[(y * w + x) * 4 + 3];
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const i = (y * w + x) * 4;
    if (src.data[i + 3] > 0) {
      // Interior edge lighting. The row data only carries three shading steps
      // per material, so the figure reads flat next to the five-step tiles.
      // This adds the missing pass without touching the art: a filled pixel on
      // the UPPER-LEFT boundary of the form catches the light and warms, one on
      // the LOWER-RIGHT boundary turns away and cools toward violet. Same
      // upper-left key light the whole abbey is lit by.
      const lit = !A(x - 1, y) || !A(x, y - 1);
      const away = !A(x + 1, y) || !A(x, y + 1);
      let r = src.data[i], gg = src.data[i + 1], b = src.data[i + 2];
      if (lit && !away) {
        r = r + (255 - r) * 0.26; gg = gg + (246 - gg) * 0.24; b = b + (207 - b) * 0.16;
      } else if (away && !lit) {
        r = r * 0.74 + 11; gg = gg * 0.74 + 7; b = b * 0.78 + 18;
      }
      out.data[i] = Math.round(r); out.data[i + 1] = Math.round(gg);
      out.data[i + 2] = Math.round(b); out.data[i + 3] = 255;
    } else if (A(x - 1, y) || A(x + 1, y) || A(x, y - 1) || A(x, y + 1)) {
      /* colored outline: a darkened tint of the fill it borders (richer than flat black) */
      let nr = 0, ng = 0, nb = 0, nc = 0;
      const add = (xx, yy) => { if (xx < 0 || yy < 0 || xx >= w || yy >= h) return; const j = (yy * w + xx) * 4; if (src.data[j + 3] > 0) { nr += src.data[j]; ng += src.data[j + 1]; nb += src.data[j + 2]; nc++; } };
      add(x - 1, y); add(x + 1, y); add(x, y - 1); add(x, y + 1);
      if (nc) { nr /= nc; ng /= nc; nb /= nc; }
      // Rule 1, the same one the tiles follow: the outline is a very dark
      // version of the pixel's OWN hue, never a shared near-black. The old
      // weighting was 30% neighbour / 70% a fixed (30,18,22), so every
      // material ended up ringed in the same maroon and the hue was lost.
      // Now the neighbour dominates (scaled hard toward black) over a small
      // violet floor, so wool gets a brown-black edge, blood robes a maroon
      // one, skin a warm one, and iron a blue-black one.
      out.data[i] = Math.round(nr * 0.22 + 10);
      out.data[i + 1] = Math.round(ng * 0.22 + 6);
      out.data[i + 2] = Math.round(nb * 0.22 + 16);
      out.data[i + 3] = 255;
    }
  }
  g.putImageData(out, 0, 0);
}
function buildFrameHD(head, body, legs, pal, mirror, acc, dir) {
  const c = document.createElement('canvas');
  c.width = 40; c.height = 56;
  c.lw = 20; c.lh = 28;
  const g = c.getContext('2d');
  g.setTransform(2, 0, 0, 2, 0, 0);
  g.imageSmoothingEnabled = false;
  g.translate(1, 1);
  paintRowsHD(g, head, pal, HEAD_Y, HEAD_CELL);
  paintRowsHD(g, body, pal, BODY_Y, BODY_CELL);
  paintRowsHD(g, legs, pal, LEGS_Y, BODY_CELL);
  if (acc) {
    // Accessory painters (the cloak, and the unused hat/face sets) are authored
    // against the ORIGINAL layout — body top at 16, feet at 26, half-size cells.
    // Map that space onto the new proportions rather than rewriting each one.
    g.save();
    const sy = (FEET_Y - BODY_Y) / (FEET_Y - 16);
    g.translate(9, FEET_Y);
    g.scale(BODY_CELL / 0.5, sy);
    g.translate(-9, -FEET_Y);
    acc(g, dir, pal);                   // cloak / cap / favour, before outline
    g.restore();
  }
  g.setTransform(1, 0, 0, 1, 0, 0);
  outlineHD(c);
  if (!mirror) return c;
  const m = document.createElement('canvas');
  m.width = 40; m.height = 56;
  m.lw = 20; m.lh = 28;
  const mg = m.getContext('2d');
  mg.translate(40, 0); mg.scale(-1, 1);
  mg.drawImage(c, 0, 0);
  return m;
}
/* ---- head/face accessories, painted in logical head space over the frame.
   Head region: x 0..18 (centre 9), y 0..16; eyes ~y7-9; neck ~y15-16.
   Side view: face centres near x4. Kept within y >= -1 to avoid clipping. */
function blk(g, x, y, w, h, col) { if (!col) return; g.fillStyle = col; g.fillRect(x, y, w, h); }

const ACC_HEAD = {
  none() {},
  band(g, dir, a) {   /* gold flapper headband with a centre jewel */
    const cx = dir === 'side' ? 4 : 9, x0 = dir === 'side' ? 1 : 1.5, w = dir === 'side' ? 12 : 15;
    blk(g, x0, 3.6, w, 1.5, a.metal);
    blk(g, x0, 3.6, w, 0.5, a.metalHi);
    blk(g, cx - 1, 3.1, 2, 2, a.jewel);
    blk(g, cx - 0.4, 3.3, 0.8, 0.8, '#ffffff');
  },
  feather(g, dir, a) {   /* a single feather tucked into the hair (no headband) */
    const bx = dir === 'side' ? 8.5 : 13;
    blk(g, bx, -1, 1.1, 5.4, a.feather);
    blk(g, bx + 0.9, -1.4, 0.9, 4.0, a.feather);
    blk(g, bx + 0.3, -0.6, 0.6, 4.4, a.featherHi);
  },
  tiara(g, dir, a) {   /* slim gold circlet + crown points (legendary regalia only) */
    const cx = dir === 'side' ? 4 : 9, x0 = dir === 'side' ? 1.5 : 3, w = dir === 'side' ? 9 : 12;
    blk(g, x0, 3.5, w, 0.8, a.metal);
    blk(g, x0, 3.5, w, 0.3, a.metalHi);
    blk(g, cx - 2, 2.2, 0.8, 1.5, a.metal);
    blk(g, cx, 1.5, 0.8, 2.2, a.metal);
    blk(g, cx + 1.4, 2.2, 0.8, 1.5, a.metal);
    blk(g, cx - 0.2, 1.1, 1, 1, a.jewel);
  },
  plume(g, dir, a) {   /* a feather plume rising from the hair, held by a small clip (no band) */
    const cx = dir === 'side' ? 6 : 9;
    for (let i = 0; i < 6; i++) blk(g, cx - 1 + (i % 2), 4 - i, 1.6 - i * 0.12, 1, i < 4 ? a.feather : a.featherHi);
    blk(g, cx - 0.2, -1.4, 0.9, 6, a.featherHi);
    blk(g, cx - 1.1, 3.4, 2.4, 0.8, a.jewel);
  },
  bycocket(g, dir, a) {   // Robin Hood cap — pointed "beak" in profile, covering cap head-on
    const H = a.hat || '#2f6a38', HH = a.hatHi || '#3f8a48', HD = a.hatDark || '#1d4826';
    const FE = a.feather || '#d8c090', FH = a.featherHi || '#f2e6b8';
    if (dir === 'side') {
      // profile: cap covering the whole top of the head, with a beak jutting forward
      blk(g, 0.6, -1.0, 14.2, 3.8, H);                                 // crown front-to-back
      blk(g, 0.6, -1.0, 14.2, 1.0, HH);                                // top sheen
      blk(g, 12.6, -0.2, 2.6, 3.0, H);                                 // round the back of the crown
      blk(g, 0.6, 2.6, 14.0, 1.2, HD);                                 // rolled brim along the lower edge
      // forward-pointing beak — columns of decreasing height narrowing to the tip
      const cols = [[1.6,0.4,3.4],[0.6,0.8,2.8],[-0.3,1.2,2.1],[-1.0,1.6,1.3]];
      for (const [x,y,h] of cols) blk(g, x, y, 1.2, h, H);
      for (const [x,y,h] of cols) blk(g, x, y, 1.2, 0.6, HH);          // top-edge sheen on the beak
      blk(g, 13.4, -1.6, 1.0, 5.0, FE); blk(g, 14.2, -1.8, 0.9, 3.6, FE); // feather at the back
      blk(g, 13.8, -1.2, 0.6, 4.0, FH);
      return;
    }
    // front / back: cap covering the crown with an upturned brim (the point only shows in profile)
    blk(g, 2, -1.0, 14, 4.4, H);                // crown block
    blk(g, 2, -1.0, 14, 1.0, HH);               // top sheen
    blk(g, 1.4, 3.0, 15.2, 1.4, HD);            // rolled brim
    blk(g, 2.0, 2.4, 2.4, 1.1, HD);             // upturned brim corners
    blk(g, 13.6, 2.4, 2.4, 1.1, HD);
    if (dir !== 'up') {
      blk(g, 13.0, -1.6, 1.1, 5.6, FE); blk(g, 14.1, -1.8, 0.9, 4.2, FE); blk(g, 13.5, -1.2, 0.6, 4.6, FH);
    } else {
      blk(g, 13.0, -1.6, 1.1, 5.6, FE); blk(g, 13.5, -1.2, 0.6, 4.6, FH);
    }
  }
};
const ACC_FACE = {
  none() {},
  rose(g, dir, a) {   // a lady's favour / flower token pinned to the chest
    const x = dir === 'side' ? 3 : 6.5, y = 18.5;
    blk(g, x, y, 1.6, 1.6, a.jewel);
    blk(g, x + 0.4, y + 0.4, 0.7, 0.7, a.jewelHi);
  }
};
/* full-body cloak, drawn over the body/legs in sprite space (before the outline) */
function drawCloak(g, dir, cl) {
  const B = cl.base, H = cl.hi, S = cl.sh;
  if (dir === 'side') {
    blk(g, 7.5, 14.4, 6.8, 2.6, B); blk(g, 7.5, 14.4, 6.8, 0.8, H);   // shoulder / upper back
    blk(g, 9.0, 16.6, 5.6, 10, B);                                     // back drape to the feet
    blk(g, 9.0, 16.6, 1, 10, H); blk(g, 13.6, 16.6, 1, 10, S);
    blk(g, 6.6, 15.0, 2.0, 2.0, H);                                    // clasp at the throat
    return;
  }
  blk(g, 3.5, 14.3, 12, 2.7, B); blk(g, 3.5, 14.3, 12, 0.8, H);        // shoulder mantle / collar
  blk(g, 3.3, 16.6, 4.8, 10, B); blk(g, 3.3, 16.6, 1, 10, H);          // left panel to the feet
  blk(g, 10.9, 16.6, 4.8, 10, B); blk(g, 14.7, 16.6, 1, 10, S);        // right panel to the feet
  if (dir === 'up') blk(g, 7.7, 16.6, 3.4, 10, B);                     // back fully covered
  blk(g, 8.4, 14.8, 2.2, 2.2, H);                                      // clasp / brooch
}
function accPainter(t, ax) {
  const hf = ACC_HEAD[t.headAcc] || ACC_HEAD.none;
  const ff = ACC_FACE[t.faceAcc] || ACC_FACE.none;
  return (g, dir) => { if (ax.cloak) drawCloak(g, dir, ax.cloak); ff(g, dir, ax); hf(g, dir, ax); };
}

export function makeCharacterHD(t) {
  return makeCharacterHD_human(t);
}
function makeCharacterHD_human(t) {
  const skin = ramp(mixc('#e8c88a', t.skin || '#e8c88a', 0.22)), hat = rampWool(t.hat), coat = rampWool(t.coat);
  const pants = rampWool(t.pants), hair = ramp(t.hair), shoes = ramp(t.shoes);
  const shirt = rampSoft(t.shirt || '#f4ead2');
  const leather = rampLeather(t.leather || '#5a3a1d');
  const metalR = ramp(t.metal || '#d9c07a');
  const pal = {
    '2': hat.hi, H: hat.base, h: hat.sh,
    '1': skin.hi, S: skin.base, s: skin.sh,
    K: hair.base, k: hair.sh,
    '3': coat.hi, J: coat.base, j: coat.sh,
    L: mixc(t.trim || coat.sh, '#1a1220', 0.28),      // #11 contrast trim (lapels / tabard edge)
    C: shirt.base, R: t.tie || '#b02a3c',
    T: leather.base, Y: leather.hi,                   // per-character leather belt / jerkin
    G: metalR.hi, g: metalR.base,                     // #3 buttons / buckles match the token's metal
    E: t.iris || '#1a1216', W: '#fff6e6', M: t.mouth || '#8e4a42',
    // Beak and talon keratin. Harder and yellower than plumage or cloth, so it
    // gets its own two steps rather than borrowing the skin or leather ramp.
    P: t.beak || '#b9d13f', p: mixc(t.beak || '#b9d13f', '#2a2410', 0.45),
    B: pants.base, b: pants.sh, F: shoes.base, f: shoes.sh
  };
  // A bare figure. Every garment cell becomes the HEAD's exact skin ramp.
  //
  // Setting the garment colours to the skin colour is not enough, and that is
  // what was wrong: the head is built with ramp(), the coat and pants with
  // rampWool() and the belt with rampLeather(), and those three mix their
  // highlights and shadows differently. Same base colour, three different
  // materials — so the body read as a skin-coloured garment rather than as
  // skin, and rampLeather's highlight (56% toward cream) drew a bright band
  // across the waist that looked exactly like a thin belt.
  if (t.bare) {
    pal['3'] = skin.hi; pal.J = skin.base; pal.j = skin.sh;      // coat
    pal.B = skin.base; pal.b = skin.sh;                          // legs
    pal.C = skin.base; pal.R = skin.base;                        // shirt, tie
    pal.T = skin.base; pal.Y = skin.base;                        // the belt, gone
    pal.L = skin.sh;                                             // trim
    pal.F = skin.base; pal.f = skin.sh;                          // shoes
    pal.G = skin.base; pal.g = skin.base;                        // buttons, buckles
  }
  const metal = ramp(t.metal || '#d9c07a');
  const jewel = ramp(t.jewel || '#b02a3c');
  const bycol = t.bycocketCol ? ramp(t.bycocketCol) : ramp('#2f6a38');
  const ax = {
    metal: metal.base, metalHi: metal.hi, dark: '#1c1620', band: t.jewel || '#7a1a26',
    jewel: jewel.base, jewelHi: jewel.hi, tie2: t.tie || '#1a1216',
    feather: (t.feather && ramp(t.feather).base) || '#e9dfce',
    featherHi: (t.feather && ramp(t.feather).hi) || '#fff8ea',
    hat: bycol.base, hatHi: bycol.hi, hatDark: mixc(bycol.sh, '#0d1a0e', 0.35),
    cloak: t.cloak ? rampWool(t.cloak) : null   // the habit's cloak is wool, not glossy
  };
  const acc = (t.cloak || (t.headAcc && t.headAcc !== 'none') || (t.faceAcc && t.faceAcc !== 'none'))
    ? accPainter(t, ax) : null;
  const legStyle = t.legs || (t.body === 'gown' ? 'gown' : ['dress','fringe','beaded','wrap'].includes(t.body) ? 'dress' : 'suit');
  const hd = lttpHead(t.head || 'fez'), bd = HD_BODIES[t.body || 'suit'], lg = HD_LEGS[legStyle] || HD_LEGS.suit;
  const out = {};
  out.down  = [0,1].map(f => buildFrameHD(hd.down, bd.front, lg.front[f], pal, false, acc, 'down'));
  out.up    = [0,1].map(f => buildFrameHD(hd.up,   bd.front, lg.front[f], pal, false, acc, 'up'));
  out.left  = [0,1].map(f => buildFrameHD(hd.side, bd.side,  lg.side[f],  pal, false, acc, 'side'));
  out.right = [0,1].map(f => buildFrameHD(hd.side, bd.side,  lg.side[f],  pal, true,  acc, 'side'));
  return out;
}
/* ================= unique Nile-era characters (NFT collection) =================
   A character is pure data: traitsForToken(id) is deterministic, so token #N
   always renders the same guest. Rendered fronts ship as a zip; when a wallet
   owns a token, the game loads that token's traits for the player sprite. */

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ===================== Aeterna trait pool (1200 AD English abbey) =====================
// Monastic dress, not Egyptian: undyed-wool habits in the colors real
// medieval orders wore -- Franciscan brown/grey, Cistercian undyed cream,
// Benedictine black -- with muted pewter/bronze fittings and subdued
// liturgical accent colors. Weathered, austere, earthen.
const AETERNA_SKIN = ['#f2cba0', '#e9b98c', '#d9ac84', '#c68a5e', '#a9714a', '#8a5a38'];
const AETERNA_HAIR = ['#2a1c12', '#3a2718', '#5a3a1e', '#4a4440', '#7a736a', '#161210'];

// Undyed wool, lifted about one value step from the original pool. The abbey
// floor is now indigo flagstone at #423a6c; the old habits (#26241f, #2e2b24)
// sat at almost exactly that value, so a walking monk dissolved into the
// floor. LttP keeps a hard value gap between a figure and the ground it
// stands on — these still read as Franciscan brown, Cistercian grey and
// Benedictine near-black, just clear of the stone.
const AETERNA_ROBE = ['#6b5138', '#575249', '#3a3730', '#7a6547', '#464238', '#65593f', '#4e4a41'];

// Fittings come off the WORLD's metal ramps so a monk's buckle agrees with the
// brazier rims and the door keystones. Most brethren wear humble pewter and
// bronze; true gold stays rare, because gold is half of the abbey's only
// accent pair and cheapens the moment everyone has it.
const AETERNA_METAL = [IRON.b, IRON.l, mixc(IRON.l, GOLD.d, 0.55), GOLD.d];
// Liturgical accents, drawn from the world's accent ramps rather than a
// separate muddy set: altar crimson, cloister green, gilt, and soul violet.
const AETERNA_JEWEL = [BLOOD.d, MOSS.d, GOLD.d, SOUL.d, mixc(WOOD.b, GOLD.o, 0.4)];
// Linen tops out at BONE.l, not BONE.h — near-white on a 20px sprite reads as
// a specular hit, and the brightest value in the frame should be a highlight,
// not a whole garment.
const AETERNA_LINEN = [BONE.l, BONE.b, mixc(BONE.b, BONE.l, 0.5), '#cfd0d4'];
const AETERNA_LEATHER = [WOOD.d, WOOD.o, WOOD.b, mixc(WOOD.d, WOOD.o, 0.5)];
const AETERNA_IRIS = ['#241a12', '#1a2436', MOSS.o, SOUL.o];
// Brethren are hooded by default — an order of monks should read as one at a
// glance, at 20px, without depending on a cult-regalia roll that the player and
// their peers never get. One slot in four is left bare so a tonsure or a plain
// head still turns up in a crowd.
// Hooded three times in four, bare-headed the fourth — the same mix the human
// cast had, so a courtyard still reads as mostly cowls with a few uncovered
// heads among them. Sex no longer changes the head: a green bird is a green
// bird, and the difference was only ever hair.
// No hoods anywhere. The cowl was the human cast's silhouette; on a bird it
// swallows the skull and the beak is the only thing left saying what this is.
const HEADS_M_HUMAN = ['cowl', 'cowl', 'cowl', 'bald'];
const HEADS_F_HUMAN = ['cowl', 'cowl', 'cowl', 'wavy'];
const HEADS_M = ['bird'];
const HEADS_F = ['bird'];

/* ONE SWITCH FOR THE WHOLE BIRD ABBEY.
   Everything the swap touches reads this and nothing else does. Set it to
   false and the human cast comes back exactly as it was: same heads, same
   rolled robe colours, same legs. No revert commit, no untangling — the bird
   glyphs stay defined and simply go unused, which costs a few kilobytes of
   dead data and buys a one-word undo.

   A URL override is honoured as well, so a DEPLOYED build can be looked at
   both ways without redeploying: ?birds=0 forces humans, ?birds=1 forces
   birds. That is the fastest possible rollback — it needs no deploy at all,
   only a link — and it is also how to check whether a bug is the birds' fault
   or was always there. */
export const BIRDS = (() => {
  try {
    const q = new URLSearchParams(location.search).get('birds');
    if (q === '0' || q === 'off') return false;
    if (q === '1' || q === 'on') return true;
  } catch { /* not in a browser */ }
  return true;                 // <-- flip to false to restore the humans
})();

// The abbey's whole palette for its people: one green, one grey, one keratin.
const PLUMAGE = '#6fbb42';      // the green from the reference
const HABIT_GREY = '#8f8f88';   // every cultist, novice and passer-by
const BEAK = '#b9d13f';         // beak and talons

// Deterministic Cultist traits from a wallet-id/name seed, in the same shape
// makeCharacterHD expects. Always cloaked (a hooded wool habit), tonsured or
// plain-haired (no Egyptian headwear), robe/cloak colors from the monastic
// wool palette above rather than jewel tones.
export function traitsForSeed(seed, sex) {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) h = (Math.imul(h ^ seed.charCodeAt(i), 16777619)) >>> 0;
  const rnd = mulberry32(h);
  const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
  const female = sex === 'female';

  // THE ABBEY IS BIRDS. One plumage, one habit, for everyone who is not the
  // Abbot or the Confessor. The colour used to be rolled per cultist, which
  // is what made a crowd read as a crowd of individuals; a congregation in one
  // identical grey habit reads instead as an ORDER, which is the point. Rank
  // is now carried by cloth alone — white is the two offices and nothing else.
  const skin = BIRDS ? PLUMAGE : jitterCol(pick(AETERNA_SKIN), (h * 2246822519) >>> 0, 0.3);
  const hair = BIRDS ? PLUMAGE : pick(AETERNA_HAIR);
  const robe = BIRDS ? HABIT_GREY : jitterCol(pick(AETERNA_ROBE), (h * 40503 + 7) >>> 0, 0.8);
  const metal = pick(AETERNA_METAL);
  const jewel = pick(AETERNA_JEWEL);
  const cloak = BIRDS ? HABIT_GREY : jitterCol(pick(AETERNA_ROBE), (h * 0x9e3779b1) >>> 0, 0.6);

  return {
    head: BIRDS ? 'bird' : pick(female ? HEADS_F_HUMAN : HEADS_M_HUMAN),
    body: BIRDS ? 'birdrobe' : (female ? pick(['dress', 'gown']) : pick(['suit', 'vest'])),
    legs: BIRDS ? 'bird' : (female ? undefined : 'suit'),
    beak: BEAK,
    skin, hair,
    hat: robe, coat: robe, pants: mixc(robe, '#0d0a12', 0.35),
    shoes: '#120d10',
    metal, jewel, tie: jewel,
    shirt: pick(AETERNA_LINEN),
    leather: pick(AETERNA_LEATHER),
    iris: pick(AETERNA_IRIS),
    trim: metal,
    mouth: '#8e4a42',
    feather: metal,
    headAcc: 'none',
    faceAcc: 'none',
    cloak,
  };
}

// The Abbot: the abbey's presiding figure, and one of only two characters
// dressed in white. That is the whole point of him — every cultist, spirit and
// wandering NPC wears near-black under violet stone, so a white robe is the one
// silhouette that reads instantly from across the nave. Gold is the mark of his
// office, and nobody else in the abbey carries it.
//
// White is built off the BONE ramp rather than pure #ffffff — a flat white
// would blow out against the palette and lose every fold, while BONE's warm
// off-whites still shade and still belong to the abbey. Only the outline and
// the deepest shadow stay dark, so the robe keeps an edge against the pale
// flagstones behind him.
export function traitsForGuru() {
  return {
    head: BIRDS ? 'bird' : 'cowl',
    body: BIRDS ? 'birdrobe' : 'vest',
    legs: BIRDS ? 'bird' : 'suit',
    beak: BEAK,
    skin: BIRDS ? PLUMAGE : '#e6bd92', hair: BIRDS ? PLUMAGE : '#cfc8b4',
    hat: BONE.h, coat: BONE.h, pants: BONE.l,
    shoes: BONE.d,
    metal: GOLD.b, jewel: BLOOD.d, tie: BONE.d,
    shirt: '#fbf8e6', leather: BONE.d, iris: '#1a1216', trim: GOLD.b,
    mouth: '#8e4a42', feather: GOLD.b,
    headAcc: 'none', faceAcc: 'none',
    cloak: BONE.h,
  };
}

// The Confessor: the monk who keeps the booth in the north niche of the west
// transept arm. Also in white, because he holds an office too — but a plainer
// one, so nothing about him competes with the Abbot at the altar. The
// differences are all subtractive: no gold anywhere (that is the Abbot's
// alone), a deeper hood, and a single crimson cord at the waist, which is the
// only saturated colour on him and reads at a glance as the streak he is
// there to restore.
export function traitsForConfessor() {
  return {
    head: BIRDS ? 'bird' : 'cowl',
    body: BIRDS ? 'birdrobe' : 'vest',
    legs: BIRDS ? 'bird' : 'suit',
    beak: BEAK,
    skin: BIRDS ? PLUMAGE : '#d8ae86', hair: BIRDS ? PLUMAGE : '#8a8069',
    hat: BONE.l, coat: BONE.h, pants: BONE.l,
    shoes: BONE.o,
    metal: IRON.l, jewel: BLOOD.b, tie: BLOOD.d,
    shirt: '#e8e2c8', leather: BONE.d, iris: '#1a1216', trim: BLOOD.d,
    mouth: '#8e4a42', feather: BONE.d,
    headAcc: 'none', faceAcc: 'none',
    cloak: BONE.l,
  };
}

// A cultist with the habit off, for the rite at the shrine — the only time
// anyone in the abbey is out of their robe.
//
// Built by recolouring rather than by new sprite rows: every material on the
// figure — habit, shirt, legs, shoes, trim — is set to the wearer's own skin,
// and the hood comes off in favour of a plain head. Nothing is added back on
// top: the figure is bare skin from the crown down.
//
// It stays readable because the glyph rows still carry three shading steps, so
// the ramp puts a lit side, a base and a shadow on what is now one colour, and
// the body keeps its form instead of flattening into a silhouette. No anatomy
// is drawn at any point — at twenty-one pixels tall there is nothing there to
// draw, and skin tone is the whole of it.
export function traitsForNaked(seed, sex) {
  const t = traitsForSeed(seed, sex);
  const skin = t.skin;
  return {
    ...t,
    head: BIRDS ? 'bird' : (sex === 'female' ? 'wavy' : 'bald'),
    // Both sexes take the vest/suit construction rather than the gown one.
    // A dress glyph recoloured to skin is still a dress SHAPE — it would read
    // as a skin-coloured robe rather than as a body — whereas vest over suit
    // legs gives a torso and two legs, which is what a bare figure needs.
    body: 'vest', legs: 'suit',
    // `bare` makes the palette build every garment cell from the head's own
    // skin ramp — see makeCharacterHD. The colours below still matter as a
    // fallback, but they are no longer what makes the figure read as skin.
    bare: true,
    hat: skin, coat: skin, pants: skin, shirt: skin, shoes: skin,
    leather: skin, trim: skin, tie: skin,
    cloak: null,
    headAcc: 'none', faceAcc: 'none',
  };
}

